#include "runner_output_directories.h"
#include <cassert>
#include <fstream>
#include <iostream>
namespace sr=suitecut::runner;namespace af=sr::attachment_files;namespace od=sr::output_directory_files;namespace fs=std::filesystem;
struct Proof{
 fs::path root;sr::RunnerOutputDirectories::Budget budget;size_t physical=0;std::vector<std::string> failures;sr::RunnerOutputDirectories actor;sr::OutputDirectoryOwner owner{1,1,1,getpid()};
 explicit Proof(fs::path path):root(std::move(path)),actor("/proc/self/exe",{[this](const auto&e){failures.push_back(e);}},budget,{&physical,1}){fs::create_directories(root);for(const auto&[key,file]:std::vector<std::pair<std::string,std::string>>{{"MARKER","writer"},{"RELEASE","writer-release"},{"CLEANUP_MARKER","cleanup"},{"CLEANUP_RELEASE","cleanup-release"}})assert(!setenv(("SUITECUT_OUTPUT_TEST_"+key).c_str(),(root/file).c_str(),1));unsetenv("SUITECUT_OUTPUT_TEST_EXIT_ZERO");unsetenv("SUITECUT_OUTPUT_TEST_CLEANUP_DENY");}
 void Begin(unsigned ms=5000){assert(actor.Begin(owner,root/"out",af::Now()+ms,af::Now()));}
 void Marker(const char* name){const auto end=af::Now()+6000;while(!fs::exists(root/name)){assert(af::Now()<end);actor.Tick(af::Now());poll(nullptr,0,1);}actor.Tick(af::Now());}
 void Release(const char* name){std::ofstream file(root/name);file<<"actual syscall release";}
 void Drain(){const auto end=af::Now()+7000;while(actor.Physical()){assert(af::Now()<end);actor.Tick(af::Now());if(actor.Physical())poll(nullptr,0,1);}assert(!physical);}
 const sr::OutputDirectoryRecord& Done(){const auto* actual=actor.Find(owner);assert(actual&&actual->writer_received&&actual->received);return *actual;}
};
int main(int argc,char**argv){
 if(argc==2&&std::string_view(argv[1])=="--native-output-directory-worker")return od::Worker();
 if(argc==2&&std::string_view(argv[1])=="--native-output-directory-cleanup")return od::Cleanup();
 assert(argc==2);assert(!setenv("LD_PRELOAD",argv[1],1));char name[]="/tmp/suitecut-output-physical-XXXXXX";assert(mkdtemp(name));const fs::path root=name;unsigned groups=0;
 {Proof p(root/"raw-and-rollback-exits");setenv("SUITECUT_OUTPUT_TEST_HOLD","both",1);p.Begin();p.Marker("writer");const auto* pending=p.actor.Observe(p.owner);assert(pending&&pending->created&&!pending->ready_receipt&&p.physical==1&&!p.actor.Find(p.owner));const auto path=pending->path;assert(fs::is_directory(path));p.actor.Cancel(p.owner,"Actual native cancellation",af::Now());p.Marker("cleanup");pending=p.actor.Observe(p.owner);assert(pending&&pending->writer_signaled&&pending->writer_exit==SIGKILL&&pending->rollback_pid>0&&p.physical==1&&!p.actor.Find(p.owner)&&!fs::exists(path));auto next=p.owner;next.generation=2;assert(!p.actor.Begin(next,p.root/"out",af::Now()+5000,af::Now()));p.Release("cleanup-release");p.Drain();const auto&r=p.Done();assert(r.status==sr::OutputDirectoryStatus::Interrupted&&r.rollback_receipt&&r.rollback_exit==0&&r.cleanup_error.empty()&&p.failures.empty());++groups;}
 {Proof p(root/"original-timeout");setenv("SUITECUT_OUTPUT_TEST_HOLD","directory",1);p.Begin(150);p.Marker("writer");const auto original=p.actor.Observe(p.owner)->deadline;p.Drain();const auto&r=p.Done();assert(r.status==sr::OutputDirectoryStatus::TimedOut&&r.deadline==original&&r.writer_signaled&&r.writer_exit==SIGKILL&&r.rollback_receipt&&r.rollback_exit==0&&!fs::exists(r.path)&&p.failures.empty());++groups;}
 {Proof p(root/"actual-zero-exit-is-not-ready");setenv("SUITECUT_OUTPUT_TEST_HOLD","directory",1);setenv("SUITECUT_OUTPUT_TEST_EXIT_ZERO","1",1);p.Begin();p.Marker("writer");p.Release("writer-release");p.Drain();const auto&r=p.Done();assert(r.status==sr::OutputDirectoryStatus::Failed&&!r.writer_signaled&&r.writer_exit==0&&!r.ready_receipt&&r.rollback_receipt&&!fs::exists(r.path));++groups;}
 {Proof p(root/"foreign-child-identity");setenv("SUITECUT_OUTPUT_TEST_HOLD","directory",1);p.Begin();p.Marker("writer");const auto path=p.actor.Observe(p.owner)->path;fs::rename(path,p.root/"actual-moved-root");fs::create_directory(path);{std::ofstream foreign(fs::path(path)/"foreign");foreign<<"actual foreign bytes";}p.actor.Cancel(p.owner,"Actual cancellation after path replacement",af::Now());p.Drain();const auto&r=p.Done();assert(r.rollback_receipt&&r.foreign_preserved&&r.rollback_exit==0&&fs::is_regular_file(fs::path(path)/"foreign")&&fs::is_directory(p.root/"actual-moved-root")&&p.failures.empty());++groups;}
 {Proof p(root/"foreign-parent-identity");setenv("SUITECUT_OUTPUT_TEST_HOLD","directory",1);p.Begin();p.Marker("writer");fs::rename(p.root/"out",p.root/"actual-moved-parent");fs::create_directory(p.root/"out");{std::ofstream foreign(p.root/"out/foreign");foreign<<"actual foreign bytes";}p.actor.Cancel(p.owner,"Actual cancellation after parent replacement",af::Now());p.Drain();const auto&r=p.Done();assert(!r.rollback_receipt&&r.rollback_exit!=0&&!r.cleanup_error.empty()&&!p.failures.empty()&&fs::is_regular_file(p.root/"out/foreign")&&fs::is_directory(p.root/"actual-moved-parent"));++groups;}
 {Proof p(root/"genuine-cleanup-eacces");setenv("SUITECUT_OUTPUT_TEST_HOLD","directory",1);p.Begin();p.Marker("writer");if(geteuid()==0)setenv("SUITECUT_OUTPUT_TEST_CLEANUP_DENY","1",1);else assert(!::chmod((p.root/"out").c_str(),0000));p.actor.Cancel(p.owner,"Actual cancellation before unprivileged rollback",af::Now());p.Drain();assert(!::chmod((p.root/"out").c_str(),0700));const auto&r=p.Done();assert(r.status==sr::OutputDirectoryStatus::Interrupted&&!r.rollback_receipt&&r.rollback_exit!=0&&r.cleanup_error.find("errno=13")!=std::string::npos&&!p.failures.empty()&&fs::is_directory(r.path));++groups;}
 fs::remove_all(root);std::cout<<"PASS"<<groups<<" real output directory writer/rollback/timeout/foreign-inode/syscall fault groups\n";
}
